#!/usr/bin/env python3
"""Generate a self-contained SVG/HTML map from actual GeoJSON and calculation report."""
import argparse,json,math,html,re,pathlib
p=argparse.ArgumentParser();p.add_argument('input');p.add_argument('result');p.add_argument('report');p.add_argument('output');a=p.parse_args()
source=json.load(open(a.input));result=json.load(open(a.result));report=json.load(open(a.report));report=report.get('report',report)
summary=next(f['properties'] for f in result['features'] if f['properties']['object_type']=='variant_summary' and f['properties']['rank']==1)
missing={str(x) for x in summary['unconnected_oks_ids']}
connected=sum(f['properties']['object_type']=='oks_connection_point' for f in source['features'])-len(missing)
status_text=f'Подключено {connected} из {connected+len(missing)}.' + (' Не подключены: '+', '.join(sorted(missing)) if missing else ' Все цели подключены.')

variant=summary['variant_id'];new=[f for f in result['features'] if f['properties']['variant_id']==variant and f['geometry']]
targets=[f for f in source['features'] if f['properties']['object_type']=='oks_connection_point'];byid={str(f['properties']['id']):f for f in source['features']}
from map_geometry import utm,coords,bounds
def path(g):
 t=g['type'];v=g['coordinates'];rings=[v] if t=='LineString' else [r for poly in v for r in poly] if t=='MultiPolygon' else v
 return ' '.join('M'+' L'.join(f'{x:.4f},{y:.4f}' for x,y in map(utm,r))+(' Z' if 'Polygon' in t else '') for r in rings)
def svg(box,small=False,focus=None):
 span=max(box[2:]);r=span/(65 if small else 110);font=span/(27 if small else 60)
 out=[f'<svg class="map" viewBox="{" ".join(map(str,box))}" role="img" aria-label="Схема тепловой сети" xmlns="http://www.w3.org/2000/svg">']
 for f in source['features']:
  q=f['properties'];g=f['geometry'];typ=q['object_type'];rt=q.get('restriction_type','')
  if g['type']=='Point':continue
  cl='existing' if typ=='heat_network' else 'building' if rt=='oks' else 'road' if rt in ('road','tram_tracks') else 'obstacle'
  extra=' own' if str(q['id'])==focus else ''
  out.append(f'<path class="{cl}{extra}" d="{path(g)}"><title>{html.escape(str(q["id"]))} · {html.escape(rt or typ)}</title></path>')
 for f in new:
  q=f['properties'];g=f['geometry']
  if g['type']=='LineString':
   dash=' special' if q.get('laying_method')=='special' else ''
   out.append(f'<path class="pipe{dash}" d="{path(g)}"><title>ДУ {q["diameter"]} · {q["flow_tph"]} т/ч · {q["length"]:.1f} м</title></path>')
  elif q['object_type']=='heat_chamber':
   x,y=utm(g['coordinates']);out.append(f'<rect class="chamber" x="{x-r*.55}" y="{y-r*.55}" width="{r*1.1}" height="{r*1.1}"/>')
 for f in targets:
  q=f['properties'];x,y=utm(f['geometry']['coordinates']);id=str(q['id'])
  out.append(f'<g class="target {"missing" if id in missing else ""}" data-target="{html.escape(id)}"><circle cx="{x}" cy="{y}" r="{r}"/><text x="{x+r*1.6}" y="{y-r*1.6}" font-size="{font}">{html.escape(id)}</text><title>Точка {html.escape(id)} · {q["flow_tph"]} т/ч</title></g>')
 if focus:
  for d in report['targetDiagnostics']:
   if str(d.get('ownBuildingId'))!=focus or 'selectedEntryWgs84' not in d:continue
   numbers=re.findall(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?',d['selectedEntryWgs84']);x,y=utm(list(map(float,numbers[:2])))
   out.append(f'<circle class="entry" cx="{x}" cy="{y}" r="{r*1.2}"/>')
 out.append('</svg>');return ''.join(out)
box=bounds(source['features']);insets=[];targetboxes={}
for f in targets:
 d=next(d for d in report['targetDiagnostics'] if str(d['targetId'])==str(f['properties']['id']));owner=byid.get(str(d.get('ownBuildingId')))
 targetboxes[str(f['properties']['id'])]=bounds([owner or f],18)
for id in ['2','5','10']:
 d=next(d for d in report['targetDiagnostics'] if str(d['targetId'])==id);owner=str(d['ownBuildingId'])
 caption='Ввод не построен' if id in missing else f'Прямой ввод внутри ОКС: {d["internalEntryLengthM"]:.2f} м · синий круг — ввод'
 insets.append(f'<article class="inset"><div class="inset-head"><b>Точка {id} <span>{"не подключена" if id in missing else "подключена"}</span></b><button data-focus="{id}">На карте ↗</button></div>{svg(targetboxes[id],True,owner)}<div class="caption">{caption}</div></article>')
rows=[]
for f in new:
 q=f['properties']
 if q['object_type']!='heat_network':continue
 rows.append(f'<tr><td>{html.escape(str(q["id"]))}</td><td>{q["diameter"]}</td><td>{q["flow_tph"]:.2f}</td><td>{q["length"]:.2f}</td><td>{"Специальный" if q["laying_method"]=="special" else "Обычный"}</td><td>{q["cost"]/1e6:.3f}</td></tr>')
css='''.target.missing circle{fill:#ca3d45!important}*{box-sizing:border-box}body{margin:0;background:#eef2ef;color:#18342c;font:15px system-ui,-apple-system,Segoe UI,sans-serif}header{background:#143d31;color:white;padding:25px 32px;display:flex;justify-content:space-between;align-items:center}h1{margin:0;font-size:26px;letter-spacing:.02em}header p{margin:7px 0 0;color:#bdd7ca}main{max-width:1500px;margin:auto;padding:24px}.badge{background:#d8f4b7;color:#17402d;padding:9px 14px;border-radius:22px;font-weight:700}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.stat{background:white;padding:18px 22px;border-radius:12px;border:1px solid #d6e1d9}.stat span{display:block;color:#62766c;font-size:12px;text-transform:uppercase;letter-spacing:.06em}.stat b{display:block;font-size:30px;margin-top:6px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px}.panel,.inset{background:white;border:1px solid #d6e1d9;border-radius:12px;overflow:hidden}.toolbar{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid #e5ece6;gap:10px}.toolbar b{font-size:16px}button,select{border:1px solid #bccdc2;border-radius:7px;background:white;color:#214b39;padding:7px 10px;cursor:pointer}button:hover{background:#e9f3ec}#main-map{height:640px;background:#f9fbf8;overflow:hidden;touch-action:none}svg.map{width:100%;height:100%;display:block}.map path{vector-effect:non-scaling-stroke}.building{fill:#dce4df;stroke:#b6c5bb;stroke-width:.65;fill-rule:evenodd}.own{fill:#e0edf4;stroke:#9dbbd0}.road{fill:#f0e7d5;stroke:#d2bea0;stroke-width:1;fill-rule:evenodd}.obstacle{fill:#e9dcdf;stroke:#b498a2;stroke-width:1;fill-rule:evenodd}.existing{fill:none;stroke:#6f9387;stroke-width:3}.pipe{fill:none;stroke:#ed743c;stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round}.special{stroke:#b14819;stroke-dasharray:6 3}.target circle{fill:#16825c;stroke:white;stroke-width:1.5;vector-effect:non-scaling-stroke}.target text{fill:#123e2e;font-weight:800;stroke:#fff;stroke-width:2;paint-order:stroke;vector-effect:non-scaling-stroke}.target{cursor:pointer}.chamber{fill:#294838;stroke:white;stroke-width:1;vector-effect:non-scaling-stroke}.entry{fill:#348acc;stroke:white;stroke-width:1.4;vector-effect:non-scaling-stroke}.legend{display:flex;gap:16px;flex-wrap:wrap;padding:14px 18px;border-top:1px solid #e5ece6;font-size:12px}.legend label{display:flex;gap:5px;align-items:center}.legend i{display:inline-block;width:20px;height:4px}.insets{display:grid;gap:12px}.inset .map{height:164px;background:#f9fbf8}.inset-head{padding:10px 12px;display:flex;align-items:center;justify-content:space-between}.inset-head span{font-size:11px;color:#16825c;margin-left:5px}.inset-head button{font-size:11px;padding:5px 8px}.caption{font-size:11px;color:#63766c;padding:7px 12px}.note{font-size:12px;color:#65776e;line-height:1.5;padding:14px 2px}.table-wrap{margin-top:22px;background:white;border:1px solid #d6e1d9;border-radius:12px;padding:18px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px 9px;border-bottom:1px solid #e6ede8;text-align:right}th:first-child,td:first-child{text-align:left}th{color:#65776e;font-size:11px}h2{font-size:19px;margin:0 0 12px}footer{font-size:11px;color:#6c7e74;padding:14px 0;overflow-wrap:anywhere}.hidden-layer{display:none}#selection{font-size:12px;color:#597264;padding:0 18px 12px}@media(max-width:950px){.layout{grid-template-columns:1fr}.insets{grid-template-columns:repeat(3,1fr)}.stats{grid-template-columns:repeat(2,1fr)}header{padding:20px}main{padding:15px}}@media(max-width:650px){.insets{grid-template-columns:1fr}header{display:block}.badge{display:inline-block;margin-top:12px}.stat b{font-size:24px}.toolbar{flex-wrap:wrap}#main-map{height:480px}}'''
js='''const map=document.querySelector('#main-map svg'),initial=map.getAttribute('viewBox').split(' ').map(Number),boxes=TARGETBOXES,missing=MISSINGIDS,statusText=STATUSTEXT;let v=initial.slice(),drag=null;
function show(){map.setAttribute('viewBox',v.join(' '))}function fit(){v=initial.slice();show();document.getElementById('selection').textContent=statusText}function zoom(k){let w=v[2]*k,h=v[3]*k;if(w<5||w>initial[2]*6)return;v=[v[0]+(v[2]-w)/2,v[1]+(v[3]-h)/2,w,h];show()}function focus(id){if(!boxes[id])return;v=boxes[id].slice();show();document.getElementById('selection').textContent='Точка '+id+(missing.includes(id)?' · не подключена':' · подключена')}
document.querySelector('#fit').onclick=fit;document.querySelector('#plus').onclick=()=>zoom(.7);document.querySelector('#minus').onclick=()=>zoom(1/.7);document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focus(b.dataset.focus));document.querySelectorAll('#main-map [data-target]').forEach(g=>g.onclick=()=>focus(g.dataset.target));map.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?.85:1.18)},{passive:false});map.onpointerdown=e=>{if(e.target.closest('[data-target]'))return;drag=[e.clientX,e.clientY,...v];map.setPointerCapture(e.pointerId)};map.onpointermove=e=>{if(!drag)return;const scale=Math.max(v[2]/map.clientWidth,v[3]/map.clientHeight);v[0]=drag[2]-(e.clientX-drag[0])*scale;v[1]=drag[3]-(e.clientY-drag[1])*scale;show()};map.onpointerup=map.onpointercancel=()=>drag=null;document.querySelectorAll('[data-layer]').forEach(c=>c.onchange=()=>document.querySelectorAll('#main-map .'+c.dataset.layer).forEach(p=>p.classList.toggle('hidden-layer',!c.checked)));'''.replace('TARGETBOXES',json.dumps(targetboxes).replace('<', '\\u003c'))
js=js.replace('MISSINGIDS',json.dumps(sorted(missing))).replace('STATUSTEXT',json.dumps(status_text,ensure_ascii=False))
out=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OPTIMUS HeatRoute — результат расчёта</title><style>{css}</style></head><body><header><div><h1>OPTIMUS HeatRoute</h1><p>Результат расчёта исправленного конкурсного датасета · 144 объекта</p></div><div class="badge">{connected} / {len(targets)} подключены</div></header><main><section class="stats"><div class="stat"><span>Строительство</span><b>{summary['construction_cost']/1e6:.2f} млн ₽</b></div><div class="stat"><span>Новая сеть</span><b>{summary['new_network_length']/1000:.3f} км</b></div><div class="stat"><span>Штраф</span><b>{summary['unconnected_penalty']/1e6:.2f} млн ₽</b></div><div class="stat"><span>Итоговый показатель S</span><b>{summary['score']:.3f}</b></div></section><div class="layout"><section class="panel"><div class="toolbar"><b>Схема подключения</b><div><button id="fit">Вся сеть</button> <button id="plus" aria-label="Увеличить">+</button> <button id="minus" aria-label="Уменьшить">−</button></div></div><div id="main-map">{svg(box)}</div><div class="legend"><label><input type="checkbox" data-layer="pipe" checked><i style="background:#ed743c"></i>Новая сеть</label><label><input type="checkbox" data-layer="existing" checked><i style="background:#6f9387"></i>Существующая сеть</label><label><input type="checkbox" data-layer="building" checked>Здания</label><span>■ камера · ● потребитель · пунктир: специальный проход</span></div><div id="selection">{status_text}</div></section><aside class="insets">{''.join(insets)}</aside></div><p class="note">Карта построена по фактическим координатам GeoJSON в метрической проекции EPSG:32637. Правило ввода: {html.escape(report["entryPolicy"])}. Допустимый прямой ввод выбирается по стоимости маршрута; геометрически ближайшая граница не обязательна. Это выбранная пользователем трактовка: соответствие требованию ближайшей границы в § 2.2 позднего приложения не заявляется. Геометрия исходных объектов сохранена. Красные точки не подключены. Глобальный минимум не доказан.</p><section class="table-wrap"><h2>Ведомость новых участков · {len(rows)}</h2><table><thead><tr><th>Участок</th><th>ДУ, мм</th><th>Расход, т/ч</th><th>Длина, м</th><th>Проход</th><th>Стоимость, млн ₽</th></tr></thead><tbody>{''.join(rows)}</tbody></table></section><footer>Fingerprint: {html.escape(summary['fingerprint'])}<br>Автономная визуализация: внешние карты, сетевые запросы и сторонние библиотеки не используются.</footer></main><script>{js}</script></body></html>'''
dest=pathlib.Path(a.output);dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out,encoding='utf-8');print(dest)
